import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import '../../../shared/models/task_view.dart'; import '../../../shared/widgets/app_card.dart'; import '../../../shared/widgets/app_async_state.dart'; import '../providers/task_view_provider.dart';
class TaskViewsPage extends ConsumerStatefulWidget{const TaskViewsPage({super.key});@override ConsumerState<TaskViewsPage> createState()=>_S();}
class _S extends ConsumerState<TaskViewsPage>{@override void initState(){super.initState();Future.microtask(()=>ref.read(taskViewProvider.notifier).load());}
Future<void> edit([TaskView? v])async{final n=TextEditingController(text:v?.name);final f=TextEditingController(text:v?.filters??'[]');final s=TextEditingController(text:v?.sortRules??'[]');final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(v==null?'新建视图':'编辑视图'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'名称')),TextField(controller:f,maxLines:3,decoration:const InputDecoration(labelText:'筛选规则 JSON')),TextField(controller:s,maxLines:3,decoration:const InputDecoration(labelText:'排序规则 JSON'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('取消')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('保存'))]));if(ok==true)await ref.read(taskViewProvider.notifier).save(id:v?.id,name:n.text.trim(),filters:f.text,sortRules:s.text,hidden:v?.hidden??false);}
@override Widget build(BuildContext context){final vs=ref.watch(taskViewProvider);return Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('任务视图'),actions:[AppGlassIconButton(icon:Icons.add,onTap:()=>edit())]),body:AppAsyncState(loading:false,error:null,empty:vs.isEmpty,emptyText:'暂无任务视图',onRetry:()=>ref.read(taskViewProvider.notifier).load(),child:ReorderableListView(onReorder:(a,b){final x=[...vs];if(b>a)b--;x.insert(b,x.removeAt(a));ref.read(taskViewProvider.notifier).reorder(x);},padding:const EdgeInsets.all(20),children:[for(final v in vs)AppCard(key:ValueKey(v.id),margin:const EdgeInsets.only(bottom:8),child:ListTile(title:Text(v.name),subtitle:Text(v.hidden?'已隐藏':'可见'),onTap:()=>edit(v),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>ref.read(taskViewProvider.notifier).delete(v.id))))])));}}
